import{_ as s,l as u,o as e,c as i,v as t,p as n,x as r,d as c,i as l,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"Postgres 元组版本与 vacuum","description":"","frontmatter":{"title":"Postgres 元组版本与 vacuum","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pg-vacuum.md","filePath":"cs/pg-vacuum.md","lastUpdated":1789023840000}'),m={name:"cs/pg-vacuum.md"};function p(h,a,_,E,B,x){const o=u("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="postgres-元组版本与-vacuum" tabindex="-1">Postgres 元组版本与 vacuum <a class="header-anchor" href="#postgres-元组版本与-vacuum" aria-label="Permalink to &quot;Postgres 元组版本与 vacuum&quot;">​</a></h1><div class="epigraph"><p>更新写新堆元组、旧元组打 xmax；vacuum 在所有快照都看不见后回收空间，冻结避免事务 id 回卷。</p><footer>—— 据 PostgreSQL MVCC 文档；Bernstein 多版本；Gray</footer></div><p><a href="/cs/undo-redo-doublewrite">上一课</a>把 InnoDB undo 链与堆版本对照。本课专钉 Postgres：没有 undo 表空间当主路径，行版本就在堆上。主干 <a href="/cs/mvcc">MVCC</a> 已给可见性直觉；进阶要 <strong>vacuum、冻结、膨胀</strong>，否则对照课只停在口号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>插入：新元组 xmin=当前 xid。删除：xmax=当前 xid，行还在。更新：删+插（或 HOT 更新若索引列不变、同页有空）。读者按快照比较 xmin/xmax。缺口是垃圾：死元组占页，索引仍可能指它们直到清理。VACUUM：扫堆，回收死元组，修剪索引，更新冻结 xid，刷新统计（常一起 ANALYZE）。</p><p>长事务/槽位：老快照挡住回收，表膨胀。这是 MVCC GC 课的 Postgres 实例，本课先给机制。</p><p><span class="marginnote">HOT（Heap Only Tuple）减少二级索引维护。冻结把老 xmin 标成永远可见，防 xid 回卷。本课不把 autovacuum 参数表当理论。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>autovacuum 按死元组比例唤醒。手动 vacuum 锁弱于全表 rewrite。VACUUM FULL 重建表，短锁重。BRIN/可见性映射：全可见页可跳过 vacuum 扫，这是 zone 思想在 GC 上。</p><p>复制：hot_standby 查询在备库持快照，同样可挡主库回收若用反馈。冲突后课。</p>',10)),(e(),n(d,null,{default:r(()=>[l(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20UPD%5B%22%E6%9B%B4%E6%96%B0%22%5D%20--%3E%20NEW%5B%22%E6%96%B0%E5%A0%86%E5%85%83%E7%BB%84%22%5D%0A%20%20UPD%20--%3E%20DEAD%5B%22%E6%97%A7%E5%85%83%E7%BB%84%20xmax%22%5D%0A%20%20DEAD%20--%3E%20VAC%5B%22vacuum%20%E5%9B%9E%E6%94%B6%22%5D%0A%20%20SNAP%5B%22%E8%80%81%E5%BF%AB%E7%85%A7%22%5D%20--%3E%20BLOCK%5B%22%E6%8C%A1%E4%BD%8F%E5%9B%9E%E6%94%B6%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与 2Q：死空间让扫描读更多页，污染更重。与计划：膨胀后统计若未更新，代价估错。与 WAL：vacuum 写大量 redo，检查点与复制延迟上升。</p><p>InnoDB 对应 purge undo；名字不同，都是「最小快照之后的版本可丢」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲聚簇回表。也不把 vacuum 当 LSM compaction——相似都是回收，结构不同。xid 回卷是运维事故，机制是冻结。</p><p>后课默认：堆引擎必须持续 vacuum；长快照是膨胀源。聚簇索引与回表：二级索引如何找到聚簇行。</p><p>可见性映射让 vacuum 与扫描跳过全可见页，是跳过索引的 GC 亲戚。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Postgres 版本在堆上；vacuum 回收死元组并冻结 xid。</li><li>长快照导致膨胀；HOT 减少索引维护。</li><li>聚簇索引与回表下一课。</li><li>出处：PostgreSQL MVCC；Bernstein；Gray。</li></ul>',9))])}const P=s(m,[["render",p]]);export{A as __pageData,P as default};
